-- v6: «писать могут только с галочкой», админы сервиса назначают админов чатов,
-- пуши не приходят на устройство с открытым приложением, канал Bobogram.

-- ============ писать могут только пользователи с галочкой ============
alter table public.profiles add column dm_verified_only boolean not null default false;

create function private.check_dm_verified_only() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.system is null
     and exists (select 1 from public.chats where id = new.chat_id and type = 'private')
     and exists (
       select 1 from public.chat_members cm join public.profiles p on p.id = cm.user_id
       where cm.chat_id = new.chat_id and cm.user_id <> new.sender_id and p.dm_verified_only
     )
     and not exists (
       select 1 from public.profiles
       where id = new.sender_id and (verified or (role = 'admin' and not banned))
     ) then
    raise exception 'verified only' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger messages_dm_verified_only before insert on public.messages
  for each row execute function private.check_dm_verified_only();

create function public.admin_set_dm_verified_only(p_user uuid, p_on boolean) returns void
language plpgsql security definer set search_path = '' as $$
begin
  perform private.assert_admin();
  update public.profiles set dm_verified_only = p_on where id = p_user;
  if not found then return; end if;
  perform private.bot_log(case when p_on
    then '✔️ Администратор ' || private.uname(auth.uid()) || ' включил(а) для ' || private.uname(p_user)
      || ' «писать могут только с галочкой»'
    else '✔️ Администратор ' || private.uname(auth.uid()) || ' выключил(а) для ' || private.uname(p_user)
      || ' «писать могут только с галочкой»' end);
end $$;

-- @lvo75 пишут только пользователи с галочкой (по просьбе владельца).
update public.profiles set dm_verified_only = true where lower(username) = 'lvo75';

-- ============ админы сервиса назначают админов групп и каналов ============
create or replace function public.set_admin(p_chat uuid, p_user uuid, p_admin boolean) returns void
language plpgsql security definer set search_path = '' as $$
begin
  perform private.assert_active();
  if (select type from public.chats where id = p_chat) not in ('group', 'channel')
     or (coalesce(private.member_role(p_chat), '') <> 'owner' and not private.is_admin()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  update public.chat_members set role = case when p_admin then 'admin' else 'member' end
  where chat_id = p_chat and user_id = p_user and role <> 'owner';
end $$;

-- ============ пуши: не слать на устройство, где приложение открыто ============
alter table public.push_subscriptions add column active_until timestamptz;

create function public.set_push_active(p_endpoint text, p_active boolean) returns void
language sql security definer set search_path = '' as $$
  update public.push_subscriptions
  set active_until = case when p_active then now() + interval '75 seconds' else null end
  where endpoint = p_endpoint and user_id = auth.uid()
$$;

-- ============ канал Bobogram: логотип и @claude в админах ============
update public.chats set avatar = 'data:image/png;base64,'
where type = 'channel' and lower(title) = 'bobogram';

insert into public.chat_members (chat_id, user_id, role)
select c.id, p.id, 'admin'
from public.chats c, public.profiles p
where c.type = 'channel' and lower(c.title) = 'bobogram' and lower(p.username) = 'claude'
on conflict (chat_id, user_id) do update set role = case when public.chat_members.role = 'owner' then 'owner' else 'admin' end;

revoke execute on function
  private.check_dm_verified_only(), public.admin_set_dm_verified_only(uuid, boolean), public.set_push_active(text, boolean)
from public, anon;
revoke execute on function private.check_dm_verified_only() from authenticated;
grant execute on function public.admin_set_dm_verified_only(uuid, boolean), public.set_push_active(text, boolean),
  public.set_admin(uuid, uuid, boolean)
to authenticated;
